### C++

```cpp
#include <iostream>
#include <vector>
#include <unordered_set>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    // neighbors[i] 存储页码 i 的所有直接参见页码，用于去重
    vector<unordered_set<int>> neighbors(n + 1);
    // top10[i] 按升序存储页码 i 的前10大参见页码
    vector<vector<int>> top10(n + 1);

    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {
            int u, v;
            cin >> u >> v;
            // 若参见关系已存在，忽略
            if (neighbors[u].count(v)) continue;
            neighbors[u].insert(v);
            neighbors[v].insert(u);

            // 更新页码 u 的前10大列表
            if (top10[u].size() < 10) {
                top10[u].push_back(v);
                sort(top10[u].begin(), top10[u].end());
            } else if (v > top10[u][0]) {
                top10[u].push_back(v);
                sort(top10[u].begin(), top10[u].end());
                if (top10[u].size() > 10) top10[u].erase(top10[u].begin());
            }

            // 更新页码 v 的前10大列表
            if (top10[v].size() < 10) {
                top10[v].push_back(u);
                sort(top10[v].begin(), top10[v].end());
            } else if (u > top10[v][0]) {
                top10[v].push_back(u);
                sort(top10[v].begin(), top10[v].end());
                if (top10[v].size() > 10) top10[v].erase(top10[v].begin());
            }
        } else {
            int u, k;
            cin >> u >> k;
            int sz = top10[u].size();
            if (k > sz) {
                cout << -1 << "\n";
            } else {
                // 升序列表，第 k 大即为索引 sz - k 的元素
                cout << top10[u][sz - k] << "\n";
            }
        }
    }

    return 0;
}
